    '  it("rejects a bundle whose last event was duplicated (odd count), but accepts the original", () => {',
    '    const chain = new AuditChain();',
    '    chain.emit("a", { v: 1 });',
    '    chain.emit("b", { v: 2 });',
    '    chain.emit("c", { v: 3 });',
    '    const bundle = chain.toBundle();',
    '    expect(verifyBundle(bundle).ok).toBe(true);',
    '    const last = bundle.events[bundle.events.length - 1]!;',
    '    const duplicated = { ...bundle, events: [...bundle.events, { ...last }] };',
    '    // The Merkle root is unchanged by the duplicate (odd-layer padding),',
